<script setup lang="ts">
type Election = { id: string; name: string; status: string }
type Stats = { status: string; totals: { eligible: number; participating: number; ballots: number }; results: { code: string; title: string; totalBallots: number; participation: number; options: { number: number; label: string; votes: number; percent: number }[] }[]; anomalies: string[] }
type Audit = { id: string; actorId: string | null; electionId: string | null; action: string; target: string | null; occurredAt: string; changes: unknown }
const { request } = useApi(); const elections = ref<Election[]>([]); const electionId = ref(''); const stats = ref<Stats | null>(null); const audits = ref<Audit[]>([]); const loading = ref(false); const error = ref(''); const notice = ref('')
const current = computed(() => elections.value.find(e => e.id === electionId.value)); async function loadElections() { try { const r = await request<{ elections: Election[] }>('/api/v1/admin/elections'); elections.value = r.elections; electionId.value = elections.value[0]?.id ?? ''; if (electionId.value) await load() } catch (e) { error.value = apiErrorMessage(e) } }
async function load() { if (!electionId.value) return; loading.value = true; error.value = ''; try { const [s, a] = await Promise.all([$fetch<Stats>(`/api/v1/admin/elections/${electionId.value}/statistics`, { retry: 0 }), $fetch<{ items: Audit[] }>(`/api/v1/admin/audit?electionId=${electionId.value}`, { retry: 0 })]); stats.value = s; audits.value = a.items } catch (e) { error.value = apiErrorMessage(e) } finally { loading.value = false } }
async function exportResults(official: boolean) { try { const r = await request<{ result: unknown }>(`/api/v1/admin/elections/${electionId.value}/results.snapshot`, { action: 'EXPORT', official }); const blob = new Blob([JSON.stringify(r.result, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `${official ? 'hasil-resmi' : 'quick-count'}-${electionId.value}.json`; a.click(); URL.revokeObjectURL(url); notice.value = official ? 'Hasil resmi diekspor.' : 'Quick count diekspor.' } catch (e) { error.value = apiErrorMessage(e) } }
watch(electionId, () => { if (electionId.value) void load() }); onMounted(loadElections)
</script>
<template><section class="reports"><header class="page-header"><div><p class="eyebrow">LAPORAN</p><h1>Statistik dan audit</h1><p class="intro">Rekap agregat untuk pemeriksaan panitia. Tidak menampilkan pilihan pemilih.</p></div><label class="period-select">Periode<select v-model="electionId"><option v-for="e in elections" :key="e.id" :value="e.id">{{ e.name }} · {{ e.status }}</option></select></label></header><AppAlert v-if="error" kind="error" :message="error"/><AppAlert v-if="notice" kind="success" :message="notice"/><div v-if="loading" class="state" role="status">Memuat laporan…</div><template v-else-if="stats"><section class="metrics"><article><span>Hak dalam DPT</span><strong>{{ stats.totals.eligible }}</strong></article><article><span>Partisipasi</span><strong>{{ stats.totals.participating }}</strong></article><article><span>Suara masuk</span><strong>{{ stats.totals.ballots }}</strong></article></section><section v-if="stats.anomalies.length" class="anomaly"><h2>Rekonsiliasi perlu diperiksa</h2><ul><li v-for="item in stats.anomalies" :key="item">{{ item }}</li></ul></section><div class="report-actions"><AppButton variant="secondary" @click="exportResults(false)">Export quick count</AppButton><AppButton :disabled="!['CLOSED','PUBLISHED'].includes(stats.status)" @click="exportResults(true)">Export hasil resmi</AppButton></div><section class="results"><h2>Perolehan per kontes</h2><article v-for="contest in stats.results" :key="contest.code" class="contest"><header><div><h3>{{ contest.title }}</h3><span>{{ contest.totalBallots }} suara · {{ contest.participation }}% partisipasi</span></div></header><ol><li v-for="option in contest.options" :key="option.number"><span><b>Nomor {{ option.number }}</b> · {{ option.label }}</span><strong>{{ option.votes }} suara ({{ option.percent }}%)</strong></li></ol></article></section><section class="audit"><div class="section-heading"><h2>Audit terbaru</h2><span>{{ audits.length }} catatan</span></div><div v-if="!audits.length" class="state">Belum ada audit pada periode ini.</div><ul v-else><li v-for="item in audits" :key="item.id"><strong>{{ item.action }}</strong><span>{{ new Date(item.occurredAt).toLocaleString('id-ID') }} · target {{ item.target ?? '—' }}</span></li></ul></section></template><div v-else class="state">Belum ada periode.</div></section></template>
<style scoped>.reports{display:grid;gap:var(--space-6)}.page-header{display:flex;justify-content:space-between;align-items:end;gap:var(--space-6);flex-wrap:wrap}.eyebrow{margin:0 0 var(--space-2);color:var(--color-primary);font-size:.75rem;font-weight:700;letter-spacing:.08em}.page-header h1{margin-bottom:var(--space-2)}.intro,.metrics span,.contest header span,.audit li span,.section-heading span{margin:0;color:var(--color-text-muted)}.period-select{display:grid;gap:var(--space-1);font-size:var(--text-sm);font-weight:600}.period-select select{min-width:18rem;min-height:2.75rem;padding:var(--space-2) var(--space-3);border:1px solid var(--color-text-muted);border-radius:var(--radius);font:inherit;background:var(--color-surface)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--space-4)}.metrics article{display:grid;gap:var(--space-1);padding:var(--space-4);background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-lg)}.metrics strong{font-size:var(--text-2xl);color:var(--color-primary-strong)}.report-actions{display:flex;gap:var(--space-3);flex-wrap:wrap}.anomaly{padding:var(--space-4);background:var(--color-warning-bg);border:1px solid var(--color-warning);border-radius:var(--radius)}.anomaly h2,.results h2,.audit h2{font-size:var(--text-lg);margin:0 0 var(--space-3)}.anomaly ul{margin:0;padding-left:var(--space-6)}.results{display:grid;gap:var(--space-3)}.contest{padding:var(--space-4);background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-lg)}.contest h3{margin:0 0 var(--space-1);font-size:var(--text-base)}.contest ol{display:grid;gap:var(--space-2);margin:var(--space-4) 0 0;padding:0;list-style:none}.contest li{display:flex;justify-content:space-between;gap:var(--space-4);padding-top:var(--space-2);border-top:1px solid var(--color-border)}.section-heading{display:flex;align-items:baseline;gap:var(--space-3)}.audit ul{display:grid;gap:var(--space-2);margin:0;padding:0;list-style:none}.audit li{display:flex;justify-content:space-between;gap:var(--space-4);padding:var(--space-3);background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius);font-size:var(--text-sm)}.audit li strong,.audit li span{display:block}.state{padding:var(--space-8) var(--space-4);text-align:center;color:var(--color-text-muted);background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius)}@media(max-width:42rem){.period-select,.period-select select{width:100%;min-width:0}.metrics{grid-template-columns:1fr}.report-actions>*{width:100%}.contest li,.audit li{align-items:start;flex-direction:column}}</style>
